package org.sleepwell.app;

import org.junit.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;

/** Bounded fake-model CPU tests; never creates native audio, services or hardware. */
public final class SonarSoundWorkerTest {
 static final long WALL=1700000000000L,ORIGIN=9000000000L;
 static final class Fake implements SoundAnalysisStream.Factory {
  final CountDownLatch loadEntered=new CountDownLatch(1),allowLoad=new CountDownLatch(1),inferEntered=new CountDownLatch(1),allowInfer=new CountDownLatch(1);final AtomicInteger closed=new AtomicInteger(),calls=new AtomicInteger();volatile boolean blockLoad,blockInfer,failed,mutated;Thread owner;
  void waitFor(CountDownLatch latch){try{assertTrue("Fake worker gate timed out",latch.await(3,TimeUnit.SECONDS));}catch(InterruptedException interrupted){throw new AssertionError("Finish must not interrupt an owned model call",interrupted);}}
  public SoundAnalysisStream.Model load(){owner=Thread.currentThread();loadEntered.countDown();if(blockLoad)waitFor(allowLoad);return new SoundAnalysisStream.Model(){public float[] infer(float[] samples){assertSame(owner,Thread.currentThread());calls.incrementAndGet();inferEntered.countDown();if(blockInfer)waitFor(allowInfer);if(failed)throw new IllegalStateException("Injected model failure");for(float sample:samples)if(sample<.24||sample>.26)mutated=true;float[] result=new float[521];result[494]=.9f;return result;}public void close(){assertSame(owner,Thread.currentThread());closed.incrementAndGet();}};}
 }
 SonarSoundWorker worker(Fake f){return new SonarSoundWorker(f,(a,n,c,s)->fail("Silence should emit no event"),WALL,ORIGIN,Runnable::run);}
 void offer(SonarSoundWorker worker,int from,int count){for(int n=from;n<from+count;n++){short[] pcm=new short[1920];java.util.Arrays.fill(pcm,(short)8192);assertTrue(worker.offer(pcm,pcm.length,ORIGIN+n*40000000L,true));java.util.Arrays.fill(pcm,(short)0);}}
 SonarSoundWorker.Result end(SonarSoundWorker worker,long cut)throws Exception {CountDownLatch finished=new CountDownLatch(1);AtomicReference<SonarSoundWorker.Result> value=new AtomicReference<>();worker.finish(cut,r->{value.set(r);finished.countDown();});assertTrue("Analysis must acknowledge model cleanup",finished.await(5,TimeUnit.SECONDS));return value.get();}
 @Test public void captureBufferIsCopiedAndModelRunsOnlyOnOwnedThread()throws Exception {Fake f=new Fake();f.blockLoad=true;SonarSoundWorker worker=worker(f);offer(worker,0,1);assertTrue(f.loadEntered.await(1,TimeUnit.SECONDS));offer(worker,1,49);f.allowLoad.countDown();SonarSoundWorker.Result result=end(worker,ORIGIN+2000000000L);assertEquals(2,result.frames);assertEquals("",result.issue);assertFalse("Capture-buffer reuse must not rewrite queued audio",f.mutated);assertEquals(1,f.closed.get());assertNotSame(Thread.currentThread(),f.owner);}
 @Test public void finishIsNonblockingAndNeverInterruptsAnInflightModel()throws Exception {Fake f=new Fake();f.blockInfer=true;SonarSoundWorker worker=worker(f);offer(worker,0,25);assertTrue(f.inferEntered.await(1,TimeUnit.SECONDS));CountDownLatch ended=new CountDownLatch(1);worker.finish(ORIGIN+1000000000L,r->ended.countDown());assertEquals(1,ended.getCount());assertFalse(worker.offer(new short[1920],1920,ORIGIN+1000000000L,true));assertEquals(0,f.closed.get());f.allowInfer.countDown();assertTrue(ended.await(3,TimeUnit.SECONDS));assertEquals(1,f.closed.get());}
 @Test public void saturatedQueueExplicitlyFailsWithoutBlockingCaptureOrLeakingModel()throws Exception {Fake f=new Fake();f.blockLoad=true;SonarSoundWorker worker=worker(f);offer(worker,0,1);assertTrue(f.loadEntered.await(1,TimeUnit.SECONDS));offer(worker,1,SonarSoundWorker.CAPACITY);assertFalse(worker.offer(new short[1920],1920,ORIGIN+65*40000000L,true));assertEquals("queue",worker.issue());f.allowLoad.countDown();SonarSoundWorker.Result result=end(worker,ORIGIN+3000000000L);assertEquals("queue",result.issue);assertEquals(0,result.frames);assertEquals(1,f.closed.get());}
 @Test public void finalCutCannotProcessQueuedFuturePcmOrPadAShortCapture()throws Exception {Fake f=new Fake();f.blockLoad=true;SonarSoundWorker worker=worker(f);offer(worker,0,1);assertTrue(f.loadEntered.await(1,TimeUnit.SECONDS));offer(worker,1,49);CountDownLatch ended=new CountDownLatch(1);AtomicReference<SonarSoundWorker.Result> value=new AtomicReference<>();worker.finish(ORIGIN+500000000L,r->{value.set(r);ended.countDown();});f.allowLoad.countDown();assertTrue(ended.await(3,TimeUnit.SECONDS));assertEquals(0,value.get().frames);assertEquals("",value.get().issue);assertEquals(0,f.calls.get());assertEquals(1,f.closed.get());}
 @Test public void earlyModelFailureRetainsAnAcknowledgedOneShotFinishResult()throws Exception {Fake f=new Fake();f.failed=true;SonarSoundWorker worker=worker(f);offer(worker,0,25);assertTrue(f.inferEntered.await(1,TimeUnit.SECONDS));SonarSoundWorker.Result result=end(worker,ORIGIN+1000000000L);assertEquals("model",result.issue);assertEquals(0,result.frames);assertEquals(1,f.closed.get());assertThrows(IllegalStateException.class,()->worker.finish(ORIGIN+2000000000L,r->fail()));}
 @Test public void invalidCaptureAdmissionDoesNotLoadAModel()throws Exception {Fake f=new Fake();SonarSoundWorker worker=worker(f);assertFalse(worker.offer(new short[4],5,ORIGIN,true));SonarSoundWorker.Result result=end(worker,ORIGIN);assertEquals("capture",result.issue);assertEquals(0,result.frames);assertEquals(0,f.closed.get());assertEquals(1,f.loadEntered.getCount());}
}
